package com.android.tools.lint.checks;

import static com.android.SdkConstants.ATTR_NAME;
import static com.android.SdkConstants.ATTR_REQUIRED;
import static com.android.SdkConstants.ATTR_VALUE;
import static com.android.SdkConstants.TAG_APPLICATION;
import static com.android.SdkConstants.TAG_META_DATA;
import static com.android.SdkConstants.TAG_USES_FEATURE;

import com.android.tools.lint.detector.api.Category;
import com.android.tools.lint.detector.api.Detector;
import com.android.tools.lint.detector.api.Implementation;
import com.android.tools.lint.detector.api.Issue;
import com.android.tools.lint.detector.api.Location;
import com.android.tools.lint.detector.api.Scope;
import com.android.tools.lint.detector.api.Severity;
import com.android.tools.lint.detector.api.XmlContext;
import com.android.tools.lint.detector.api.XmlScanner;
import java.util.Collection;
import java.util.Collections;
import org.jetbrains.annotations.NotNull;
import org.w3c.dom.Attr;
import org.w3c.dom.Document;
import org.w3c.dom.Element;
import org.w3c.dom.Node;

public class WearStandaloneAppDetector extends Detector implements XmlScanner {

    private static final String STANDALONE_FLAG = "com.google.android.wearable.standalone";
    private static final String FEATURE_WATCH = "android.hardware.type.watch";

    public static final Issue ISSUE = Issue.create(
            "WearStandaloneAppFlag",
            "Invalid or missing Wear standalone app flag",
            "Wearable apps should specify whether they can work standalone, without a phone app. "
                    + "Add a valid meta-data entry for `com.google.android.wearable.standalone` to "
                    + "your application element and set the value to `true` or `false`.",
            Category.WEAR,
            6,
            Severity.WARNING,
            new Implementation(WearStandaloneAppDetector.class, Scope.MANIFEST_SCOPE),
            "https://developer.android.com/training/wearables/apps/packaging.html"
    );

    @Override
    @NotNull
    public Collection<String> getApplicableElements() {
        return Collections.singletonList(TAG_APPLICATION);
    }

    @Override
    public void visitElement(@NotNull XmlContext context, @NotNull Element element) {
        if (!isWearApp(context.document)) {
            return;
        }

        boolean found = false;
        Node child = element.getFirstChild();
        while (child != null) {
            if (child.getNodeType() == Node.ELEMENT_NODE
                    && TAG_META_DATA.equals(child.getNodeName())) {
                Element meta = (Element) child;
                if (STANDALONE_FLAG.equals(meta.getAttribute(ATTR_NAME))) {
                    found = true;
                    String value = meta.getAttribute(ATTR_VALUE);
                    if (!"true".equals(value) && !"false".equals(value)) {
                        Attr valueAttr = meta.getAttributeNode(ATTR_VALUE);
                        Location location = valueAttr != null
                                ? context.getValueLocation(valueAttr)
                                : context.getLocation(meta);
                        context.report(ISSUE, location,
                                "The `com.google.android.wearable.standalone` meta-data value must be `true` or `false`.");
                    }
                    break;
                }
            }
            child = child.getNextSibling();
        }

        if (!found) {
            context.report(ISSUE, context.getLocation(element),
                    "Wear apps must specify the `com.google.android.wearable.standalone` meta-data element with a value of `true` or `false`.");
        }
    }

    private static boolean isWearApp(@NotNull Document document) {
        NodeList features = document.getElementsByTagName(TAG_USES_FEATURE);
        for (int i = 0, n = features.getLength(); i < n; i++) {
            Element feature = (Element) features.item(i);
            if (FEATURE_WATCH.equals(feature.getAttribute(ATTR_NAME))) {
                String required = feature.getAttribute(ATTR_REQUIRED);
                if (required == null || required.isEmpty()
                        || !Boolean.parseBoolean(required)) {
                    // required defaults to true; if explicitly false, not a watch app
                    if ("false".equalsIgnoreCase(required)) {
                        continue;
                    }
                }
                return true;
            }
        }
        return false;
    }
}
